typedef unsigned int u_int;

class vector3d {
public:
    float x, y, z;
};

template <int n> struct SplineCoeffs {
    float a[n], b[n], c[n], d[n];
};

typedef struct {
    SplineCoeffs<16> y, z;
} WaveProfileCoeffs;

struct WavePositionHint {
    float x, z;
    float xprofile;
    u_int xcell, zcell;
    u_int xgrid, zgrid;
    WaveProfileCoeffs wpc;
};

struct WaveControlPoints {
    char data[6144];
    u_int numcontrol, numprofile;
};

static float WAVE_ControlZ[16];
static float WAVE_GrindGridX[16];
static SplineCoeffs<16> WAVE_GrindCoeffs;
static u_int WAVE_NumGrindCoeffs;
static WaveControlPoints WAVE_ControlPointsArray[1];
static WaveControlPoints *WAVE_ControlPoints = WAVE_ControlPointsArray;

void WAVE_BuildHint(WavePositionHint *, float, float, float, const WaveProfileCoeffs &);

inline u_int SPLINE_BinarySearch(const float *x, u_int n, const float &valx)
{
    u_int lo = 0, hi = n - 1, mid;
    while (hi - lo > 1)
    {
        mid = (lo + hi) / 2;
        if (x[mid] < valx) lo = mid;
        else hi = mid;
    }
    return lo;
}

inline float SPLINE_Evaluate(const float *x, const float *a, const float *b, const float *c, const float *d,
    u_int n, float valx)
{
    u_int lo = SPLINE_BinarySearch(x, n, valx);
    valx -= x[lo];
    return ((a[lo] * valx + b[lo]) * valx + c[lo]) * valx + d[lo];
}

inline float SPLINE_Evaluate(const float *x, const float *a, const float *b, const float *c, const float *d,
    u_int n, float valx, u_int lo)
{
    valx -= x[lo];
    return ((a[lo] * valx + b[lo]) * valx + c[lo]) * valx + d[lo];
}

void WAVE_GetGrindPosition(const WavePositionHint *hintin, WavePositionHint *hintout,
    const vector3d &posin, vector3d *posout)
{
    const float &x0 = posin.x, &profilex0 = hintin->xprofile;
    const SplineCoeffs<16> &wgc = WAVE_GrindCoeffs;

    float grindz = SPLINE_Evaluate(WAVE_GrindGridX, wgc.a, wgc.b, wgc.c, wgc.d, WAVE_NumGrindCoeffs, profilex0);
    WAVE_BuildHint(hintout, x0, profilex0, grindz, hintin->wpc);

    const WaveProfileCoeffs wpc = hintin->wpc;

    posout->x = x0;
    posout->y = SPLINE_Evaluate(WAVE_ControlZ, wpc.y.a, wpc.y.b, wpc.y.c, wpc.y.d, WAVE_ControlPoints->numcontrol,
        grindz, hintout->zcell);
    posout->z = SPLINE_Evaluate(WAVE_ControlZ, wpc.z.a, wpc.z.b, wpc.z.c, wpc.z.d, WAVE_ControlPoints->numcontrol,
        grindz, hintout->zcell);
}
